// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(address target, uint256 amount, bytes memory data) public {
        vm.assume(target != address(c));
        vm.assume(amount <= address(this).balance);
        vm.deal(address(this), amount);
        uint256 depositsBefore = c.depositsCount();
        vm.prank(c.owner());
        (bool ok,) = address(c).call(abi.encodeWithSelector(SimpleWallet.sendMoney.selector, target, amount, data));
        uint256 depositsAfter = c.depositsCount();
        assertTrue(ok ? (depositsAfter == depositsBefore) : true);
    }
}
